Agent orchestration.code:
def run(task, model, tools, max_steps=6):
    state = [{"role": "user", "content": task}]
    for _ in range(max_steps):
        step = model(state)                  # decide: answer or call a tool
        if step["type"] == "answer":
            return step["text"]
        result = tools[step["tool"]](**step["args"])
        state.append({"role": "tool", "content": result})
    return "Stopped: step limit reached"

