TOOLS = {
    "get_status": {"args": {"project": str}, "run": lambda project: f"{project}: Live"},
}

def call(name, args):
    spec = TOOLS[name]                      # an unknown tool raises KeyError
    for key, kind in spec["args"].items():
        if not isinstance(args.get(key), kind):
            raise ValueError(f"bad argument: {key}")
    return spec["run"](**args)

